begin;
select no_plan();
select has_function('public','create_customer_order',array['jsonb'],'atomic order transaction exists');
insert into auth.users(id,email,email_confirmed_at,is_anonymous) values
 ('b1000000-0000-4000-8000-000000000001','c3-admin@example.invalid',now(),false),
 ('b1000000-0000-4000-8000-000000000002','c3-a@example.invalid',now(),false),
 ('b1000000-0000-4000-8000-000000000003','c3-b@example.invalid',now(),false),
