create function pg_temp.fixture_snapshot() returns jsonb language sql as $$
 select jsonb_build_object('messages',jsonb_object_agg(locale,jsonb_build_object('Legal',jsonb_build_object('eyebrow','Legal','draft','Draft','terms',(select jsonb_object_agg(k,'test '||k) from unnest(array['title','intro','p1','h1','p2','h2','p3','h3','p4','h4','p5']) k)),'Products',jsonb_build_object('shipping','Shipping','returns','Returns','warranty','Warranty')))) from unnest(array['en','zh-hant','ja']) locale;
$$;
insert into public.content_drafts(id,version,snapshot,created_by,updated_by) values('b2000000-0000-4000-8000-000000000001',1,pg_temp.fixture_snapshot()||'{"settings":{}}','b1000000-0000-4000-8000-000000000001','b1000000-0000-4000-8000-000000000001');
insert into public.content_releases(id,snapshot,draft_id,draft_version,created_by) values ('b2000000-0000-4000-8000-000000000002',pg_temp.fixture_snapshot(),'b2000000-0000-4000-8000-000000000001',1,'b1000000-0000-4000-8000-000000000001');
update public.content_publication set release_id='b2000000-0000-4000-8000-000000000002';
create function pg_temp.sku(product text) returns uuid language sql security definer as $$select id from public.catalog_offerings where product_id=product$$;
create function pg_temp.request(key text default 'test-key-01',product text default 'ola',quantity numeric default 2) returns jsonb language sql as $$
 select jsonb_build_object('idempotencyKey',key,'items',jsonb_build_array(jsonb_build_object('skuId',pg_temp.sku(product),'quantity',quantity)),'shippingAddress','{"name":"Test","country":"US","region":"CA","city":"Test","postalCode":"123","line1":"Test","line2":"","phone":""}'::jsonb,'termsVersion','b2000000-0000-4000-8000-000000000002');
$$;
select is((select count(*)::int from public.catalog_offerings),5,'all five products mapped');
select is((select count(*)::int from public.catalog_offerings where confirmed or enabled or unit_minor is not null or currency is not null),0,'no invented confirmed initial prices');
select is((select orders_enabled from public.commerce_settings),false,'initial ordering disabled');
set local role anon;
select is(public.get_ordering_catalog()->>'unavailableReason','ORDERING_DISABLED','public catalog switch-off explicit');
select is(public.get_ordering_catalog()->'offerings','[]'::jsonb,'public does not expose unconfirmed offerings');
select is(public.get_ordering_catalog()->'terms','null'::jsonb,'public does not expose unapproved terms');
select throws_ok($$select * from public.catalog_offerings$$,'42501',null,'no anonymous direct catalog table grant');
reset role;
set local role anon;
select throws_ok($$select public.create_customer_order(pg_temp.request())$$,'42501',null,'anonymous cannot order');
set local role authenticated;
set local request.jwt.claims='{"sub":"b1000000-0000-4000-8000-000000000004","role":"authenticated","email_verified":true}';
select throws_ok($$select public.create_customer_order(pg_temp.request())$$,'42501',null,'DB Auth rejects unverified even with forged metadata');
set local request.jwt.claims='{"sub":"b1000000-0000-4000-8000-000000000002","role":"authenticated"}';
select throws_ok($$select public.create_customer_order(pg_temp.request())$$,'P0004',null,'ordering switch rejects new order');
select throws_ok($$select public.set_catalog_offering(pg_temp.sku('ola'),'USD',100,true,true,0)$$,'42501',null,'customer cannot confirm price');
select throws_ok($$select public.create_customer_order(pg_temp.request()||'{"unitMinor":1}')$$,'22023',null,'client price forbidden');
select throws_ok(format('select public.create_customer_order(%L::jsonb)',pg_temp.request()||'{"userId":"b1000000-0000-4000-8000-000000000003"}'),'22023',null,'forged owner forbidden');
select throws_ok(format('select public.create_customer_order(%L::jsonb)',pg_temp.request('invalid-q', 'ola',0)),'22023',null,'zero quantity rejected');
select throws_ok(format('select public.create_customer_order(%L::jsonb)',pg_temp.request('invalid-q', 'ola',-1)),'22023',null,'negative quantity rejected');
select throws_ok(format('select public.create_customer_order(%L::jsonb)',pg_temp.request('invalid-q', 'ola',1.2)),'22023',null,'fractional quantity rejected');
select throws_ok(format('select public.create_customer_order(%L::jsonb)',pg_temp.request('invalid-q', 'ola',100)),'22023',null,'over99 rejected');
select throws_ok(format('select public.create_customer_order(%L::jsonb)',pg_temp.request('invalid-q', 'ola',9007199254740992)),'22023',null,'unsafe quantity rejected');
select throws_ok($$select public.create_customer_order(jsonb_set(pg_temp.request(),'{shippingAddress,country}','"ZZ"'))$$,'22023',null,'invalid country rejected directly');
select throws_ok($$select public.create_customer_order(jsonb_set(pg_temp.request(),'{items}',(pg_temp.request()->'items')||(pg_temp.request()->'items')))$$,'22023',null,'duplicate SKU rejected');
set local request.jwt.claims='{"sub":"b1000000-0000-4000-8000-000000000005","role":"authenticated"}';
select throws_ok($$select public.set_catalog_offering(pg_temp.sku('ola'),'USD',100,true,true,0)$$,'42501',null,'editor cannot confirm price');
set local request.jwt.claims='{"sub":"b1000000-0000-4000-8000-000000000006","role":"authenticated"}';
select throws_ok($$select public.update_commerce_settings(true,'b2000000-0000-4000-8000-000000000002',0)$$,'42501',null,'operations cannot enable orders');
set local request.jwt.claims='{"sub":"b1000000-0000-4000-8000-000000000001","role":"authenticated"}';
select throws_ok($$select public.update_commerce_settings(true,null,0)$$,'22023',null,'enabling requires approved terms');
select throws_ok($$select public.set_catalog_offering(pg_temp.sku('ola'),'USD',1.5,true,true,0)$$,'22023',null,'SQL price cannot round fractional amount');
select throws_ok($$select public.set_catalog_offering(pg_temp.sku('ola'),'USD',9007199254740992,true,true,0)$$,'22023',null,'unsafe admin price rejected');
select throws_ok($$select public.set_catalog_offering(pg_temp.sku('ola'),'USD',-1,true,true,0)$$,'22023',null,'negative admin price rejected');
select throws_ok($$select public.set_catalog_offering(pg_temp.sku('ola-go'),'USD',0,true,true,0)$$,'22023',null,'Go cannot be separately confirmed even for zero');
select public.update_commerce_settings(true,'b2000000-0000-4000-8000-000000000002',0);
set local request.jwt.claims='{"sub":"b1000000-0000-4000-8000-000000000002","role":"authenticated"}';
select throws_ok($$select public.create_customer_order(pg_temp.request())$$,'P0004',null,'unconfirmed SKU rejected');
select throws_ok($$select public.create_customer_order(pg_temp.request('go-order','ola-go'))$$,'P0004',null,'Go independent order rejected');
set local request.jwt.claims='{"sub":"b1000000-0000-4000-8000-000000000001","role":"authenticated"}';
select public.set_catalog_offering(pg_temp.sku('ola'),'USD',123,true,true,0);
select public.set_catalog_offering(pg_temp.sku('tablet'),'JPY',100,true,true,0);
set local role anon;
select is(public.get_ordering_catalog()->>'orderingEnabled','true','anonymous public catalog correctly allows submission');
select is(jsonb_array_length(public.get_ordering_catalog()->'offerings'),2,'only confirmed enabled standalone offers returned');
select is((select array_agg(k order by k) from jsonb_object_keys(public.get_ordering_catalog()->'offerings'->0) k),array['currency','name','productId','skuId','unitMinor','version'],'public offer exact projection has no admin fields');
select is(public.get_ordering_catalog()#>>'{terms,releaseId}','b2000000-0000-4000-8000-000000000002','approved immutable release ID exposed');
select is(public.get_ordering_catalog()#>>'{terms,locales,ja,terms,p3}','test p3','approved locale terms returned');
select is((select count(*)::int from jsonb_object_keys(public.get_ordering_catalog()#>'{terms,locales}')),3,'three approved locales returned');
set local role authenticated;
select throws_ok($$select public.set_catalog_offering(pg_temp.sku('ola'),'USD',124,true,true,0)$$,'23505',null,'stale admin version conflicts');
set local request.jwt.claims='{"sub":"b1000000-0000-4000-8000-000000000002","role":"authenticated"}';
select throws_ok($$select public.create_customer_order(jsonb_set(pg_temp.request(),'{items}',(pg_temp.request()->'items')||(pg_temp.request('mixed-key','tablet')->'items')))$$,'22023',null,'mixed currencies rejected');
create temporary table first_result as select public.create_customer_order(pg_temp.request()) as value;
select is((select value#>>'{order,totals,itemsMinor}' from first_result),'246','server computes integer subtotal');
select is((select value#>'{order,totals,shippingMinor}' from first_result),'null'::jsonb,'shipping pending');
select is((select value#>'{order,totals,taxMinor}' from first_result),'null'::jsonb,'tax pending');
select is((select value#>'{order,totals,payableMinor}' from first_result),'null'::jsonb,'payable not claimed');
select is((select value->>'reused' from first_result),'false','first create not reused');
select is(public.create_customer_order(pg_temp.request())#>>'{order,id}',(select value#>>'{order,id}' from first_result),'same customer retry same order');
select is(public.create_customer_order(pg_temp.request())->>'reused','true','retry reports reused');
select throws_ok($$select public.create_customer_order(pg_temp.request('test-key-01','ola',3))$$,'23505',null,'same key changed request conflicts');
select is((public.list_customer_orders(1,25)->>'total')::int,1,'one own order');
select throws_ok($$select public.list_customer_orders(0,25)$$,'22023',null,'SQL pagination validated');
select throws_ok($$update public.customer_orders set status='cancelled'$$,'42501',null,'cannot bypass cancellation RPC');
select throws_ok($$update public.order_items set unit_minor=1$$,'42501',null,'cannot mutate historical item');
set local request.jwt.claims='{"sub":"b1000000-0000-4000-8000-000000000003","role":"authenticated"}';
select isnt(public.create_customer_order(pg_temp.request())#>>'{order,id}',(select value#>>'{order,id}' from first_result),'same key different customer distinct order');
select is((select count(*)::int from public.customer_orders),1,'RLS only own order visible');
select is((select count(*)::int from public.order_items),1,'RLS only own items visible');
select throws_ok(format('select public.get_customer_order(%L)',(select value#>>'{order,id}' from first_result)),'P0002',null,'B cannot get A');
select throws_ok(format('select public.cancel_customer_order(%L)',(select value#>>'{order,id}' from first_result)),'P0002',null,'B cannot cancel A');
set local request.jwt.claims='{"sub":"b1000000-0000-4000-8000-000000000001","role":"authenticated"}';
select public.set_catalog_offering(pg_temp.sku('ola'),'USD',999,true,true,1);
select public.update_commerce_settings(false,null,1);
set local request.jwt.claims='{"sub":"b1000000-0000-4000-8000-000000000002","role":"authenticated"}';
select is(public.create_customer_order(pg_temp.request())#>>'{order,items,0,unitMinor}','123','retry retains price after change and switch/terms removed');
select is(public.cancel_customer_order((select (value#>>'{order,id}')::uuid from first_result))->>'status','cancelled','cancel succeeds');
select is(public.create_customer_order(pg_temp.request())#>>'{order,status}','cancelled','cancelled retry never reopens');
select is(public.cancel_customer_order((select (value#>>'{order,id}')::uuid from first_result))->>'status','cancelled','repeat cancellation is harmless');
reset role;
select is((select count(*)::int from public.audit_events where entity_id=(select (value#>>'{order,id}')::uuid from first_result) and action='orders.created'),1,'one creation audit');
select is((select count(*)::int from public.audit_events where entity_id=(select (value#>>'{order,id}')::uuid from first_result) and action='orders.cancelled'),1,'one cancellation audit');
update auth.users set email_confirmed_at=null where id='b1000000-0000-4000-8000-000000000002';
set local role authenticated;
select throws_ok($$select public.create_customer_order(pg_temp.request())$$,'42501',null,'retry rechecks real verification');
select is((select count(*)::int from public.customer_orders),0,'RLS verification revoked hides orders');
reset role;
update auth.users set email_confirmed_at=now() where id='b1000000-0000-4000-8000-000000000002';
