-- A new immutable release with only unrelated homepage fields keeps approved terms equivalent.
insert into public.content_releases(id,snapshot,draft_id,draft_version,created_by) values ('b2000000-0000-4000-8000-000000000003',pg_temp.fixture_snapshot()||'{"home":"unrelated"}','b2000000-0000-4000-8000-000000000001',1,'b1000000-0000-4000-8000-000000000001');
update public.content_publication set release_id='b2000000-0000-4000-8000-000000000003';
set local role authenticated;
select lives_ok($$select public.create_customer_order(pg_temp.request('unchanged-terms','tablet',1))$$,'unrelated publication retains approved terms');
select is(public.get_ordering_catalog()->>'orderingEnabled','true','unrelated publication also leaves public availability enabled');
reset role;
insert into public.content_releases(id,snapshot,draft_id,draft_version,created_by) values ('b2000000-0000-4000-8000-000000000004',jsonb_set(pg_temp.fixture_snapshot(),'{messages,ja,Legal,terms,p3}','"New payments terms"'),'b2000000-0000-4000-8000-000000000001',1,'b1000000-0000-4000-8000-000000000001');
update public.content_publication set release_id='b2000000-0000-4000-8000-000000000004';
set local role authenticated;
select throws_ok($$select public.create_customer_order(pg_temp.request('changed-terms','tablet',1))$$,'P0004',null,'legal change blocks new order pending approval');
select is(public.get_ordering_catalog()->>'unavailableReason','TERMS_CHANGED','public availability fails closed on legal change');
select is(public.get_ordering_catalog()#>>'{terms,locales,ja,terms,p3}','test p3','public projection retains original approved terms not unapproved current text');
select is(jsonb_array_length(public.get_ordering_catalog()->'offerings'),2,'configured offers remain distinct from disabled submission');
select is(public.create_customer_order(pg_temp.request('unchanged-terms','tablet',1))->>'reused','true','legal change does not block stored retry');
reset role;
insert into public.content_releases(id,snapshot,draft_id,draft_version,created_by) values ('b2000000-0000-4000-8000-000000000005',jsonb_set(pg_temp.fixture_snapshot(),'{messages,zh-hant,Products,warranty}','"New warranty"'),'b2000000-0000-4000-8000-000000000001',1,'b1000000-0000-4000-8000-000000000001');
update public.content_publication set release_id='b2000000-0000-4000-8000-000000000005';
set local role authenticated;
select throws_ok($$select public.create_customer_order(pg_temp.request('changed-promise','tablet',1))$$,'P0004',null,'warranty change blocks new order');
select is(public.get_ordering_catalog()->>'orderingEnabled','false','promise change fails closed in public read');
set local request.jwt.claims='{"sub":"b1000000-0000-4000-8000-000000000001","role":"authenticated"}';
select throws_ok($$select public.update_commerce_settings(true,'b2000000-0000-4000-8000-000000000002',3)$$,'22023',null,'cannot approve historical noncurrent terms');

reset role;
-- Every fixed legal/promise dependency, every locale, contributes; unrelated marketing does not.
select isnt(private.commercial_terms_fingerprint(jsonb_set(pg_temp.fixture_snapshot(),array['messages',locale,'Products',key],'"changed"')),private.commercial_terms_fingerprint(pg_temp.fixture_snapshot()),locale||' '||key||' promise invalidates approval') from unnest(array['en','zh-hant','ja']) locale cross join unnest(array['shipping','returns','warranty']) key;
select isnt(private.commercial_terms_fingerprint(jsonb_set(pg_temp.fixture_snapshot(),array['messages',locale,'Legal','terms','p1'],'"changed"')),private.commercial_terms_fingerprint(pg_temp.fixture_snapshot()),locale||' legal text invalidates approval') from unnest(array['en','zh-hant','ja']) locale;
select throws_ok($$select private.commercial_terms_fingerprint(jsonb_set(pg_temp.fixture_snapshot(),'{messages,en,Products,shipping}','null'))$$,'22023',null,'missing promise leaf fails closed');
update public.profiles set access_state='suspended' where user_id='b1000000-0000-4000-8000-000000000002';
set local role authenticated;
set local request.jwt.claims='{"sub":"b1000000-0000-4000-8000-000000000002","role":"authenticated"}';
select throws_ok($$select public.create_customer_order(pg_temp.request())$$,'42501',null,'suspended customer cannot retry');
select throws_ok(format('select public.cancel_customer_order(%L)',(select value#>>'{order,id}' from first_result)),'42501',null,'suspended customer cannot cancel');
reset role;
update public.profiles set access_state='active' where user_id='b1000000-0000-4000-8000-000000000002';
update public.content_publication set release_id='b2000000-0000-4000-8000-000000000002';
create function pg_temp.fail_order_audit() returns trigger language plpgsql as $$begin if new.action='orders.created' then raise exception 'audit unavailable'; end if;return new;end;$$;
create trigger c3_fail_audit before insert on public.audit_events for each row execute function pg_temp.fail_order_audit();
set local role authenticated;
select throws_ok($$select public.create_customer_order(pg_temp.request('audit-rollback','tablet',1))$$,'P0001','audit unavailable','order cannot commit without audit');
select is((select count(*)::int from public.customer_orders where idempotency_key='audit-rollback'),0,'audit failure leaves no partial order');
reset role;
drop trigger c3_fail_audit on public.audit_events;
set local role service_role;
select throws_ok($$select public.create_customer_order(pg_temp.request('service-forged','tablet',1))$$,'42501',null,'service role cannot impersonate order RPC caller');
reset role;
select * from finish();
rollback;
